    po.tariff_group_rollup AS tariff_group_rollup WITH SYNONYMS = ('tariff group rollup') COMMENT = 'Tariff grouping used by trade compliance, rolled up for executive reporting. Used by the Procurement team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    po.cost_center_rollup AS cost_center_rollup WITH SYNONYMS = ('cost center rollup') COMMENT = 'Cost center charged, rolled up for executive reporting. Used by the Procurement team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    po.profit_center_rollup AS profit_center_rollup WITH SYNONYMS = ('profit center rollup') COMMENT = 'Profit center for reporting, rolled up for executive reporting. Used by the Procurement team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.'
  )
  METRICS (
    po.total_spend_usd AS SUM(po.line_spend_usd) COMMENT = 'Total purchase spend in USD',
    po.total_units_purchased AS SUM(po.quantity) COMMENT = 'Total units purchased',
    po.po_line_count AS COUNT(po.po_line_id) COMMENT = 'Number of purchase order lines',
    po.avg_unit_price_usd AS AVG(po.unit_price_usd) COMMENT = 'Average unit price in USD'
  )
  COMMENT = 'Purchase order lines: spend by supplier, part, plant and date';

CREATE OR REPLACE TABLE MULTIAGENT_DEMO.DEMO.QUALITY_INSPECTIONS AS
SELECT
  SEQ4() AS inspection_id, DATEADD(day, -(ABS(HASH(SEQ4(), 4)) % 730), DATE '2026-11-01') AS inspection_date, 'SUP-' || LPAD((ABS(HASH(SEQ4(), 1)) % 60 + 1)::VARCHAR, 3, '0') AS supplier_id, 'PN-' || LPAD((ABS(HASH(SEQ4(), 2)) % 300 + 1)::VARCHAR, 4, '0') AS part_id, GET(ARRAY_CONSTRUCT('Lisle','Guadalajara','Penang','Shannon','Chengdu'), ABS(HASH(SEQ4(), 3)) % 5)::VARCHAR AS plant, (ABS(HASH(SEQ4(), 9)) % 2000 + 100) AS qty_inspected, IFF(ABS(HASH(SEQ4(), 10)) % 100 < 18, ABS(HASH(SEQ4(), 11)) % 12, 0) AS qty_defective, IFF(ABS(HASH(SEQ4(), 12)) % 100 < 4, 1, 0) AS ncr_raised,
  GET(ARRAY_CONSTRUCT('AMERICAS','EMEA','APAC'), ABS(HASH(SEQ4(), 101)) % 3)::VARCHAR AS plant_region,
  GET(ARRAY_CONSTRUCT('US','MX','DE','IE','CN','MY'), ABS(HASH(SEQ4(), 102)) % 6)::VARCHAR AS plant_country,
  GET(ARRAY_CONSTRUCT('Automotive','Industrial','Datacom','Medical','Consumer'), ABS(HASH(SEQ4(), 103)) % 5)::VARCHAR AS business_unit,
  GET(ARRAY_CONSTRUCT('Connectors','Cable Assemblies','Sensors','Antennas','Switches'), ABS(HASH(SEQ4(), 104)) % 5)::VARCHAR AS product_line,
  GET(ARRAY_CONSTRUCT('Metals','Plastics','Electronics','Packaging','Chemicals'), ABS(HASH(SEQ4(), 105)) % 5)::VARCHAR AS commodity_l1,
  GET(ARRAY_CONSTRUCT('Copper Alloy','Resin','PCB','Terminals','Corrugate','Plating'), ABS(HASH(SEQ4(), 106)) % 6)::VARCHAR AS commodity_l2,
  GET(ARRAY_CONSTRUCT('Prototype','Active','Mature','End of Life'), ABS(HASH(SEQ4(), 107)) % 4)::VARCHAR AS part_lifecycle,
  GET(ARRAY_CONSTRUCT('A','B','C'), ABS(HASH(SEQ4(), 108)) % 3)::VARCHAR AS part_criticality,
  GET(ARRAY_CONSTRUCT('Make','Buy'), ABS(HASH(SEQ4(), 109)) % 2)::VARCHAR AS make_or_buy,
  GET(ARRAY_CONSTRUCT('Tier 1','Tier 2','Tier 3'), ABS(HASH(SEQ4(), 110)) % 3)::VARCHAR AS supplier_tier,
  GET(ARRAY_CONSTRUCT('US','MX','CN','TW','DE','JP','IN'), ABS(HASH(SEQ4(), 111)) % 7)::VARCHAR AS supplier_country,
  GET(ARRAY_CONSTRUCT('Strategic','Preferred','Approved','Transactional'), ABS(HASH(SEQ4(), 112)) % 4)::VARCHAR AS supplier_segment,
  GET(ARRAY_CONSTRUCT('IATF 16949','ISO 9001','ISO 13485','AS9100'), ABS(HASH(SEQ4(), 113)) % 4)::VARCHAR AS supplier_certification,
  GET(ARRAY_CONSTRUCT('FCA','DAP','DDP','EXW','FOB'), ABS(HASH(SEQ4(), 114)) % 5)::VARCHAR AS incoterm,
  GET(ARRAY_CONSTRUCT('NET30','NET45','NET60','NET90'), ABS(HASH(SEQ4(), 115)) % 4)::VARCHAR AS payment_terms,
  GET(ARRAY_CONSTRUCT('USD','EUR','CNY','MXN','JPY'), ABS(HASH(SEQ4(), 116)) % 5)::VARCHAR AS currency,
  GET(ARRAY_CONSTRUCT('Direct Metals','Direct Plastics','Electronics','Indirect'), ABS(HASH(SEQ4(), 117)) % 4)::VARCHAR AS buyer_team,
  GET(ARRAY_CONSTRUCT('MRP-A','MRP-B','MRP-C','Kanban'), ABS(HASH(SEQ4(), 118)) % 4)::VARCHAR AS planner_group,
  GET(ARRAY_CONSTRUCT('Q1','Q2','Q3','Q4'), ABS(HASH(SEQ4(), 119)) % 4)::VARCHAR AS fiscal_quarter,
  GET(ARRAY_CONSTRUCT('Direct','Distribution','EMS Partner'), ABS(HASH(SEQ4(), 120)) % 3)::VARCHAR AS channel,
  GET(ARRAY_CONSTRUCT('Automotive OEM','Tier-1 Auto','Industrial','Datacenter','Medical Device'), ABS(HASH(SEQ4(), 121)) % 5)::VARCHAR AS customer_segment,
  GET(ARRAY_CONSTRUCT('EV Platform','ADAS','Hyperscale','Factory Automation','Patient Monitoring'), ABS(HASH(SEQ4(), 122)) % 5)::VARCHAR AS program,
  GET(ARRAY_CONSTRUCT('Ocean','Air','Truck','Rail'), ABS(HASH(SEQ4(), 123)) % 4)::VARCHAR AS ship_mode,
  GET(ARRAY_CONSTRUCT('None','Class 8','Class 9'), ABS(HASH(SEQ4(), 124)) % 3)::VARCHAR AS hazmat_class,
  GET(ARRAY_CONSTRUCT('Compliant','Exempt','Non-compliant'), ABS(HASH(SEQ4(), 125)) % 3)::VARCHAR AS rohs_status,
  GET(ARRAY_CONSTRUCT('Declared','Pending','Not Required'), ABS(HASH(SEQ4(), 126)) % 3)::VARCHAR AS reach_status,
  GET(ARRAY_CONSTRUCT('US','MX','CN','MY','DE'), ABS(HASH(SEQ4(), 127)) % 5)::VARCHAR AS country_of_origin,
  GET(ARRAY_CONSTRUCT('HTS-8536','HTS-8544','HTS-9031','Other'), ABS(HASH(SEQ4(), 128)) % 4)::VARCHAR AS tariff_group,
  GET(ARRAY_CONSTRUCT('CC-100','CC-200','CC-300','CC-400'), ABS(HASH(SEQ4(), 129)) % 4)::VARCHAR AS cost_center,
  GET(ARRAY_CONSTRUCT('PC-AUTO','PC-IND','PC-DC','PC-MED'), ABS(HASH(SEQ4(), 130)) % 4)::VARCHAR AS profit_center,
  GET(ARRAY_CONSTRUCT('AME0','EME1','APA2'), ABS(HASH(SEQ4(), 131)) % 3)::VARCHAR AS plant_region_code,
  GET(ARRAY_CONSTRUCT('US0','MX1','DE2','IE3','CN4','MY5'), ABS(HASH(SEQ4(), 132)) % 6)::VARCHAR AS plant_country_code,
  GET(ARRAY_CONSTRUCT('AUT0','IND1','DAT2','MED3','CON4'), ABS(HASH(SEQ4(), 133)) % 5)::VARCHAR AS business_unit_code,
  GET(ARRAY_CONSTRUCT('CON0','CAB1','SEN2','ANT3','SWI4'), ABS(HASH(SEQ4(), 134)) % 5)::VARCHAR AS product_line_code,
  GET(ARRAY_CONSTRUCT('MET0','PLA1','ELE2','PAC3','CHE4'), ABS(HASH(SEQ4(), 135)) % 5)::VARCHAR AS commodity_l1_code,
  GET(ARRAY_CONSTRUCT('COP0','RES1','PCB2','TER3','COR4','PLA5'), ABS(HASH(SEQ4(), 136)) % 6)::VARCHAR AS commodity_l2_code,
  GET(ARRAY_CONSTRUCT('PRO0','ACT1','MAT2','END3'), ABS(HASH(SEQ4(), 137)) % 4)::VARCHAR AS part_lifecycle_code,
  GET(ARRAY_CONSTRUCT('A0','B1','C2'), ABS(HASH(SEQ4(), 138)) % 3)::VARCHAR AS part_criticality_code,
  GET(ARRAY_CONSTRUCT('MAK0','BUY1'), ABS(HASH(SEQ4(), 139)) % 2)::VARCHAR AS make_or_buy_code,
  GET(ARRAY_CONSTRUCT('TIE0','TIE1','TIE2'), ABS(HASH(SEQ4(), 140)) % 3)::VARCHAR AS supplier_tier_code,
  GET(ARRAY_CONSTRUCT('US0','MX1','CN2','TW3','DE4','JP5','IN6'), ABS(HASH(SEQ4(), 141)) % 7)::VARCHAR AS supplier_country_code,
  GET(ARRAY_CONSTRUCT('STR0','PRE1','APP2','TRA3'), ABS(HASH(SEQ4(), 142)) % 4)::VARCHAR AS supplier_segment_code,
  GET(ARRAY_CONSTRUCT('IAT0','ISO1','ISO2','AS93'), ABS(HASH(SEQ4(), 143)) % 4)::VARCHAR AS supplier_certification_code,
  GET(ARRAY_CONSTRUCT('FCA0','DAP1','DDP2','EXW3','FOB4'), ABS(HASH(SEQ4(), 144)) % 5)::VARCHAR AS incoterm_code,
  GET(ARRAY_CONSTRUCT('NET0','NET1','NET2','NET3'), ABS(HASH(SEQ4(), 145)) % 4)::VARCHAR AS payment_terms_code,
  GET(ARRAY_CONSTRUCT('USD0','EUR1','CNY2','MXN3','JPY4'), ABS(HASH(SEQ4(), 146)) % 5)::VARCHAR AS currency_code,
  GET(ARRAY_CONSTRUCT('DIR0','DIR1','ELE2','IND3'), ABS(HASH(SEQ4(), 147)) % 4)::VARCHAR AS buyer_team_code,
  GET(ARRAY_CONSTRUCT('MRP0','MRP1','MRP2','KAN3'), ABS(HASH(SEQ4(), 148)) % 4)::VARCHAR AS planner_group_code,
  GET(ARRAY_CONSTRUCT('Q10','Q21','Q32','Q43'), ABS(HASH(SEQ4(), 149)) % 4)::VARCHAR AS fiscal_quarter_code,
  GET(ARRAY_CONSTRUCT('DIR0','DIS1','EMS2'), ABS(HASH(SEQ4(), 150)) % 3)::VARCHAR AS channel_code,
  GET(ARRAY_CONSTRUCT('AUT0','TIE1','IND2','DAT3','MED4'), ABS(HASH(SEQ4(), 151)) % 5)::VARCHAR AS customer_segment_code,
  GET(ARRAY_CONSTRUCT('EV 0','ADA1','HYP2','FAC3','PAT4'), ABS(HASH(SEQ4(), 152)) % 5)::VARCHAR AS program_code,
  GET(ARRAY_CONSTRUCT('OCE0','AIR1','TRU2','RAI3'), ABS(HASH(SEQ4(), 153)) % 4)::VARCHAR AS ship_mode_code,
  GET(ARRAY_CONSTRUCT('NON0','CLA1','CLA2'), ABS(HASH(SEQ4(), 154)) % 3)::VARCHAR AS hazmat_class_code,
  GET(ARRAY_CONSTRUCT('COM0','EXE1','NON2'), ABS(HASH(SEQ4(), 155)) % 3)::VARCHAR AS rohs_status_code,
  GET(ARRAY_CONSTRUCT('DEC0','PEN1','NOT2'), ABS(HASH(SEQ4(), 156)) % 3)::VARCHAR AS reach_status_code,
  GET(ARRAY_CONSTRUCT('US0','MX1','CN2','MY3','DE4'), ABS(HASH(SEQ4(), 157)) % 5)::VARCHAR AS country_of_origin_code,
  GET(ARRAY_CONSTRUCT('HTS0','HTS1','HTS2','OTH3'), ABS(HASH(SEQ4(), 158)) % 4)::VARCHAR AS tariff_group_code,
  GET(ARRAY_CONSTRUCT('CC-0','CC-1','CC-2','CC-3'), ABS(HASH(SEQ4(), 159)) % 4)::VARCHAR AS cost_center_code,
  GET(ARRAY_CONSTRUCT('PC-0','PC-1','PC-2','PC-3'), ABS(HASH(SEQ4(), 160)) % 4)::VARCHAR AS profit_center_code,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 161)) % 3)::VARCHAR AS plant_region_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 162)) % 3)::VARCHAR AS plant_country_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 163)) % 3)::VARCHAR AS business_unit_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 164)) % 3)::VARCHAR AS product_line_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 165)) % 3)::VARCHAR AS commodity_l1_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 166)) % 3)::VARCHAR AS commodity_l2_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 167)) % 3)::VARCHAR AS part_lifecycle_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 168)) % 3)::VARCHAR AS part_criticality_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 169)) % 3)::VARCHAR AS make_or_buy_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 170)) % 3)::VARCHAR AS supplier_tier_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 171)) % 3)::VARCHAR AS supplier_country_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 172)) % 3)::VARCHAR AS supplier_segment_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 173)) % 3)::VARCHAR AS supplier_certification_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 174)) % 3)::VARCHAR AS incoterm_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 175)) % 3)::VARCHAR AS payment_terms_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 176)) % 3)::VARCHAR AS currency_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 177)) % 3)::VARCHAR AS buyer_team_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 178)) % 3)::VARCHAR AS planner_group_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 179)) % 3)::VARCHAR AS fiscal_quarter_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 180)) % 3)::VARCHAR AS channel_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 181)) % 3)::VARCHAR AS customer_segment_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 182)) % 3)::VARCHAR AS program_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 183)) % 3)::VARCHAR AS ship_mode_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 184)) % 3)::VARCHAR AS hazmat_class_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 185)) % 3)::VARCHAR AS rohs_status_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 186)) % 3)::VARCHAR AS reach_status_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 187)) % 3)::VARCHAR AS country_of_origin_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 188)) % 3)::VARCHAR AS tariff_group_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 189)) % 3)::VARCHAR AS cost_center_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(SEQ4(), 190)) % 3)::VARCHAR AS profit_center_rollup
FROM TABLE(GENERATOR(ROWCOUNT => 30000));

CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.DEMO.SUPPLIER_QUALITY_SV
  TABLES (qi AS MULTIAGENT_DEMO.DEMO.QUALITY_INSPECTIONS PRIMARY KEY (inspection_id) COMMENT = 'Incoming inspection results: defects, PPM and NCRs by supplier, part and plant')
  FACTS (
    qi.qty_inspected AS qty_inspected,
    qi.qty_defective AS qty_defective,
    qi.ncr_raised AS ncr_raised
  )
  DIMENSIONS (
    qi.inspection_date AS inspection_date WITH SYNONYMS = ('inspection date') COMMENT = 'Date of incoming inspection',
    qi.supplier_id AS supplier_id WITH SYNONYMS = ('supplier', 'vendor') COMMENT = 'Supplier identifier, format SUP-###',
    qi.part_id AS part_id WITH SYNONYMS = ('part', 'part number', 'PN') COMMENT = 'Part number, format PN-####',
    qi.plant AS plant WITH SYNONYMS = ('site', 'factory') COMMENT = 'Plant where the inspection happened',
    qi.plant_region AS plant_region WITH SYNONYMS = ('plant region') COMMENT = 'Geographic region of the manufacturing plant. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: AMERICAS, EMEA, APAC. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.plant_country AS plant_country WITH SYNONYMS = ('plant country') COMMENT = 'Country where the plant operates. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: US, MX, DE, IE, CN, MY. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.business_unit AS business_unit WITH SYNONYMS = ('business unit') COMMENT = 'Business unit that owns the product line. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Automotive, Industrial, Datacom, Medical, Consumer. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.product_line AS product_line WITH SYNONYMS = ('product line') COMMENT = 'Product line of the part. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Connectors, Cable Assemblies, Sensors, Antennas, Switches. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.commodity_l1 AS commodity_l1 WITH SYNONYMS = ('commodity l1') COMMENT = 'Level-1 commodity classification. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Metals, Plastics, Electronics, Packaging, Chemicals. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.commodity_l2 AS commodity_l2 WITH SYNONYMS = ('commodity l2') COMMENT = 'Level-2 commodity classification. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Copper Alloy, Resin, PCB, Terminals, Corrugate, Plating. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.part_lifecycle AS part_lifecycle WITH SYNONYMS = ('part lifecycle') COMMENT = 'Engineering lifecycle state of the part. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Prototype, Active, Mature, End of Life. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.part_criticality AS part_criticality WITH SYNONYMS = ('part criticality') COMMENT = 'Supply criticality rating from the risk team. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: A, B, C. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.make_or_buy AS make_or_buy WITH SYNONYMS = ('make or buy') COMMENT = 'Whether the part is manufactured or purchased. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Make, Buy. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.supplier_tier AS supplier_tier WITH SYNONYMS = ('supplier tier') COMMENT = 'Supplier tier in the supply network. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Tier 1, Tier 2, Tier 3. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.supplier_country AS supplier_country WITH SYNONYMS = ('supplier country') COMMENT = 'Country of the suppliers primary site. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: US, MX, CN, TW, DE, JP, IN. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.supplier_segment AS supplier_segment WITH SYNONYMS = ('supplier segment') COMMENT = 'Strategic segmentation of the supplier. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Strategic, Preferred, Approved, Transactional. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.supplier_certification AS supplier_certification WITH SYNONYMS = ('supplier certification') COMMENT = 'Highest quality certification held. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: IATF 16949, ISO 9001, ISO 13485, AS9100. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.incoterm AS incoterm WITH SYNONYMS = ('incoterm') COMMENT = 'Incoterm on the supply agreement. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: FCA, DAP, DDP, EXW, FOB. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.payment_terms AS payment_terms WITH SYNONYMS = ('payment terms') COMMENT = 'Agreed payment terms. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: NET30, NET45, NET60, NET90. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.currency AS currency WITH SYNONYMS = ('currency') COMMENT = 'Transaction currency before conversion to USD. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: USD, EUR, CNY, MXN, JPY. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.buyer_team AS buyer_team WITH SYNONYMS = ('buyer team') COMMENT = 'Procurement team responsible. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Direct Metals, Direct Plastics, Electronics, Indirect. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.planner_group AS planner_group WITH SYNONYMS = ('planner group') COMMENT = 'Materials planning group. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: MRP-A, MRP-B, MRP-C, Kanban. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.fiscal_quarter AS fiscal_quarter WITH SYNONYMS = ('fiscal quarter') COMMENT = 'Fiscal quarter of the transaction. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Q1, Q2, Q3, Q4. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
