    qi.ship_mode_rollup AS ship_mode_rollup WITH SYNONYMS = ('ship mode rollup') COMMENT = 'Primary shipment mode, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.hazmat_class_rollup AS hazmat_class_rollup WITH SYNONYMS = ('hazmat class rollup') COMMENT = 'Hazardous material classification, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.rohs_status_rollup AS rohs_status_rollup WITH SYNONYMS = ('rohs status rollup') COMMENT = 'RoHS compliance status, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.reach_status_rollup AS reach_status_rollup WITH SYNONYMS = ('reach status rollup') COMMENT = 'REACH SVHC declaration status, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.country_of_origin_rollup AS country_of_origin_rollup WITH SYNONYMS = ('country of origin rollup') COMMENT = 'Country of origin for customs, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.tariff_group_rollup AS tariff_group_rollup WITH SYNONYMS = ('tariff group rollup') COMMENT = 'Tariff grouping used by trade compliance, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.cost_center_rollup AS cost_center_rollup WITH SYNONYMS = ('cost center rollup') COMMENT = 'Cost center charged, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    qi.profit_center_rollup AS profit_center_rollup WITH SYNONYMS = ('profit center rollup') COMMENT = 'Profit center for reporting, rolled up for executive reporting. Used by the Supplier Quality team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.'
  )
  METRICS (
    qi.total_inspected AS SUM(qi.qty_inspected) COMMENT = 'Total units inspected',
    qi.total_defective AS SUM(qi.qty_defective) COMMENT = 'Total defective units',
    qi.defect_ppm AS SUM(qi.qty_defective) * 1000000 / NULLIF(SUM(qi.qty_inspected), 0) COMMENT = 'Defect rate in parts per million (PPM). Use this for defect rate questions.',
    qi.ncr_count AS SUM(qi.ncr_raised) COMMENT = 'Number of non-conformance reports raised'
  )
  COMMENT = 'Incoming inspection results: defects, PPM and NCRs by supplier, part and plant';

CREATE OR REPLACE TABLE MULTIAGENT_DEMO.DEMO.INVENTORY_POSITIONS AS
SELECT
  ROW_NUMBER() OVER (ORDER BY p.part_id, l.plant) AS position_id, p.part_id, l.plant,
  ABS(HASH(p.part_id, l.plant, 1)) % 4000 AS on_hand_qty,
  ABS(HASH(p.part_id, l.plant, 2)) % 1500 + 500 AS safety_stock_qty,
  ABS(HASH(p.part_id, l.plant, 3)) % 300 + 20 AS avg_daily_usage,
  ROUND((ABS(HASH(p.part_id, l.plant, 4)) % 900 + 10) / 100.0, 2) AS standard_cost_usd,
  GET(ARRAY_CONSTRUCT('AMERICAS','EMEA','APAC'), ABS(HASH(p.part_id, l.plant, 101)) % 3)::VARCHAR AS plant_region,
  GET(ARRAY_CONSTRUCT('US','MX','DE','IE','CN','MY'), ABS(HASH(p.part_id, l.plant, 102)) % 6)::VARCHAR AS plant_country,
  GET(ARRAY_CONSTRUCT('Automotive','Industrial','Datacom','Medical','Consumer'), ABS(HASH(p.part_id, l.plant, 103)) % 5)::VARCHAR AS business_unit,
  GET(ARRAY_CONSTRUCT('Connectors','Cable Assemblies','Sensors','Antennas','Switches'), ABS(HASH(p.part_id, l.plant, 104)) % 5)::VARCHAR AS product_line,
  GET(ARRAY_CONSTRUCT('Metals','Plastics','Electronics','Packaging','Chemicals'), ABS(HASH(p.part_id, l.plant, 105)) % 5)::VARCHAR AS commodity_l1,
  GET(ARRAY_CONSTRUCT('Copper Alloy','Resin','PCB','Terminals','Corrugate','Plating'), ABS(HASH(p.part_id, l.plant, 106)) % 6)::VARCHAR AS commodity_l2,
  GET(ARRAY_CONSTRUCT('Prototype','Active','Mature','End of Life'), ABS(HASH(p.part_id, l.plant, 107)) % 4)::VARCHAR AS part_lifecycle,
  GET(ARRAY_CONSTRUCT('A','B','C'), ABS(HASH(p.part_id, l.plant, 108)) % 3)::VARCHAR AS part_criticality,
  GET(ARRAY_CONSTRUCT('Make','Buy'), ABS(HASH(p.part_id, l.plant, 109)) % 2)::VARCHAR AS make_or_buy,
  GET(ARRAY_CONSTRUCT('Tier 1','Tier 2','Tier 3'), ABS(HASH(p.part_id, l.plant, 110)) % 3)::VARCHAR AS supplier_tier,
  GET(ARRAY_CONSTRUCT('US','MX','CN','TW','DE','JP','IN'), ABS(HASH(p.part_id, l.plant, 111)) % 7)::VARCHAR AS supplier_country,
  GET(ARRAY_CONSTRUCT('Strategic','Preferred','Approved','Transactional'), ABS(HASH(p.part_id, l.plant, 112)) % 4)::VARCHAR AS supplier_segment,
  GET(ARRAY_CONSTRUCT('IATF 16949','ISO 9001','ISO 13485','AS9100'), ABS(HASH(p.part_id, l.plant, 113)) % 4)::VARCHAR AS supplier_certification,
  GET(ARRAY_CONSTRUCT('FCA','DAP','DDP','EXW','FOB'), ABS(HASH(p.part_id, l.plant, 114)) % 5)::VARCHAR AS incoterm,
  GET(ARRAY_CONSTRUCT('NET30','NET45','NET60','NET90'), ABS(HASH(p.part_id, l.plant, 115)) % 4)::VARCHAR AS payment_terms,
  GET(ARRAY_CONSTRUCT('USD','EUR','CNY','MXN','JPY'), ABS(HASH(p.part_id, l.plant, 116)) % 5)::VARCHAR AS currency,
  GET(ARRAY_CONSTRUCT('Direct Metals','Direct Plastics','Electronics','Indirect'), ABS(HASH(p.part_id, l.plant, 117)) % 4)::VARCHAR AS buyer_team,
  GET(ARRAY_CONSTRUCT('MRP-A','MRP-B','MRP-C','Kanban'), ABS(HASH(p.part_id, l.plant, 118)) % 4)::VARCHAR AS planner_group,
  GET(ARRAY_CONSTRUCT('Q1','Q2','Q3','Q4'), ABS(HASH(p.part_id, l.plant, 119)) % 4)::VARCHAR AS fiscal_quarter,
  GET(ARRAY_CONSTRUCT('Direct','Distribution','EMS Partner'), ABS(HASH(p.part_id, l.plant, 120)) % 3)::VARCHAR AS channel,
  GET(ARRAY_CONSTRUCT('Automotive OEM','Tier-1 Auto','Industrial','Datacenter','Medical Device'), ABS(HASH(p.part_id, l.plant, 121)) % 5)::VARCHAR AS customer_segment,
  GET(ARRAY_CONSTRUCT('EV Platform','ADAS','Hyperscale','Factory Automation','Patient Monitoring'), ABS(HASH(p.part_id, l.plant, 122)) % 5)::VARCHAR AS program,
  GET(ARRAY_CONSTRUCT('Ocean','Air','Truck','Rail'), ABS(HASH(p.part_id, l.plant, 123)) % 4)::VARCHAR AS ship_mode,
  GET(ARRAY_CONSTRUCT('None','Class 8','Class 9'), ABS(HASH(p.part_id, l.plant, 124)) % 3)::VARCHAR AS hazmat_class,
  GET(ARRAY_CONSTRUCT('Compliant','Exempt','Non-compliant'), ABS(HASH(p.part_id, l.plant, 125)) % 3)::VARCHAR AS rohs_status,
  GET(ARRAY_CONSTRUCT('Declared','Pending','Not Required'), ABS(HASH(p.part_id, l.plant, 126)) % 3)::VARCHAR AS reach_status,
  GET(ARRAY_CONSTRUCT('US','MX','CN','MY','DE'), ABS(HASH(p.part_id, l.plant, 127)) % 5)::VARCHAR AS country_of_origin,
  GET(ARRAY_CONSTRUCT('HTS-8536','HTS-8544','HTS-9031','Other'), ABS(HASH(p.part_id, l.plant, 128)) % 4)::VARCHAR AS tariff_group,
  GET(ARRAY_CONSTRUCT('CC-100','CC-200','CC-300','CC-400'), ABS(HASH(p.part_id, l.plant, 129)) % 4)::VARCHAR AS cost_center,
  GET(ARRAY_CONSTRUCT('PC-AUTO','PC-IND','PC-DC','PC-MED'), ABS(HASH(p.part_id, l.plant, 130)) % 4)::VARCHAR AS profit_center,
  GET(ARRAY_CONSTRUCT('AME0','EME1','APA2'), ABS(HASH(p.part_id, l.plant, 131)) % 3)::VARCHAR AS plant_region_code,
  GET(ARRAY_CONSTRUCT('US0','MX1','DE2','IE3','CN4','MY5'), ABS(HASH(p.part_id, l.plant, 132)) % 6)::VARCHAR AS plant_country_code,
  GET(ARRAY_CONSTRUCT('AUT0','IND1','DAT2','MED3','CON4'), ABS(HASH(p.part_id, l.plant, 133)) % 5)::VARCHAR AS business_unit_code,
  GET(ARRAY_CONSTRUCT('CON0','CAB1','SEN2','ANT3','SWI4'), ABS(HASH(p.part_id, l.plant, 134)) % 5)::VARCHAR AS product_line_code,
  GET(ARRAY_CONSTRUCT('MET0','PLA1','ELE2','PAC3','CHE4'), ABS(HASH(p.part_id, l.plant, 135)) % 5)::VARCHAR AS commodity_l1_code,
  GET(ARRAY_CONSTRUCT('COP0','RES1','PCB2','TER3','COR4','PLA5'), ABS(HASH(p.part_id, l.plant, 136)) % 6)::VARCHAR AS commodity_l2_code,
  GET(ARRAY_CONSTRUCT('PRO0','ACT1','MAT2','END3'), ABS(HASH(p.part_id, l.plant, 137)) % 4)::VARCHAR AS part_lifecycle_code,
  GET(ARRAY_CONSTRUCT('A0','B1','C2'), ABS(HASH(p.part_id, l.plant, 138)) % 3)::VARCHAR AS part_criticality_code,
  GET(ARRAY_CONSTRUCT('MAK0','BUY1'), ABS(HASH(p.part_id, l.plant, 139)) % 2)::VARCHAR AS make_or_buy_code,
  GET(ARRAY_CONSTRUCT('TIE0','TIE1','TIE2'), ABS(HASH(p.part_id, l.plant, 140)) % 3)::VARCHAR AS supplier_tier_code,
  GET(ARRAY_CONSTRUCT('US0','MX1','CN2','TW3','DE4','JP5','IN6'), ABS(HASH(p.part_id, l.plant, 141)) % 7)::VARCHAR AS supplier_country_code,
  GET(ARRAY_CONSTRUCT('STR0','PRE1','APP2','TRA3'), ABS(HASH(p.part_id, l.plant, 142)) % 4)::VARCHAR AS supplier_segment_code,
  GET(ARRAY_CONSTRUCT('IAT0','ISO1','ISO2','AS93'), ABS(HASH(p.part_id, l.plant, 143)) % 4)::VARCHAR AS supplier_certification_code,
  GET(ARRAY_CONSTRUCT('FCA0','DAP1','DDP2','EXW3','FOB4'), ABS(HASH(p.part_id, l.plant, 144)) % 5)::VARCHAR AS incoterm_code,
  GET(ARRAY_CONSTRUCT('NET0','NET1','NET2','NET3'), ABS(HASH(p.part_id, l.plant, 145)) % 4)::VARCHAR AS payment_terms_code,
  GET(ARRAY_CONSTRUCT('USD0','EUR1','CNY2','MXN3','JPY4'), ABS(HASH(p.part_id, l.plant, 146)) % 5)::VARCHAR AS currency_code,
  GET(ARRAY_CONSTRUCT('DIR0','DIR1','ELE2','IND3'), ABS(HASH(p.part_id, l.plant, 147)) % 4)::VARCHAR AS buyer_team_code,
  GET(ARRAY_CONSTRUCT('MRP0','MRP1','MRP2','KAN3'), ABS(HASH(p.part_id, l.plant, 148)) % 4)::VARCHAR AS planner_group_code,
  GET(ARRAY_CONSTRUCT('Q10','Q21','Q32','Q43'), ABS(HASH(p.part_id, l.plant, 149)) % 4)::VARCHAR AS fiscal_quarter_code,
  GET(ARRAY_CONSTRUCT('DIR0','DIS1','EMS2'), ABS(HASH(p.part_id, l.plant, 150)) % 3)::VARCHAR AS channel_code,
  GET(ARRAY_CONSTRUCT('AUT0','TIE1','IND2','DAT3','MED4'), ABS(HASH(p.part_id, l.plant, 151)) % 5)::VARCHAR AS customer_segment_code,
  GET(ARRAY_CONSTRUCT('EV 0','ADA1','HYP2','FAC3','PAT4'), ABS(HASH(p.part_id, l.plant, 152)) % 5)::VARCHAR AS program_code,
  GET(ARRAY_CONSTRUCT('OCE0','AIR1','TRU2','RAI3'), ABS(HASH(p.part_id, l.plant, 153)) % 4)::VARCHAR AS ship_mode_code,
  GET(ARRAY_CONSTRUCT('NON0','CLA1','CLA2'), ABS(HASH(p.part_id, l.plant, 154)) % 3)::VARCHAR AS hazmat_class_code,
  GET(ARRAY_CONSTRUCT('COM0','EXE1','NON2'), ABS(HASH(p.part_id, l.plant, 155)) % 3)::VARCHAR AS rohs_status_code,
  GET(ARRAY_CONSTRUCT('DEC0','PEN1','NOT2'), ABS(HASH(p.part_id, l.plant, 156)) % 3)::VARCHAR AS reach_status_code,
  GET(ARRAY_CONSTRUCT('US0','MX1','CN2','MY3','DE4'), ABS(HASH(p.part_id, l.plant, 157)) % 5)::VARCHAR AS country_of_origin_code,
  GET(ARRAY_CONSTRUCT('HTS0','HTS1','HTS2','OTH3'), ABS(HASH(p.part_id, l.plant, 158)) % 4)::VARCHAR AS tariff_group_code,
  GET(ARRAY_CONSTRUCT('CC-0','CC-1','CC-2','CC-3'), ABS(HASH(p.part_id, l.plant, 159)) % 4)::VARCHAR AS cost_center_code,
  GET(ARRAY_CONSTRUCT('PC-0','PC-1','PC-2','PC-3'), ABS(HASH(p.part_id, l.plant, 160)) % 4)::VARCHAR AS profit_center_code,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 161)) % 3)::VARCHAR AS plant_region_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 162)) % 3)::VARCHAR AS plant_country_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 163)) % 3)::VARCHAR AS business_unit_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 164)) % 3)::VARCHAR AS product_line_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 165)) % 3)::VARCHAR AS commodity_l1_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 166)) % 3)::VARCHAR AS commodity_l2_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 167)) % 3)::VARCHAR AS part_lifecycle_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 168)) % 3)::VARCHAR AS part_criticality_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 169)) % 3)::VARCHAR AS make_or_buy_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 170)) % 3)::VARCHAR AS supplier_tier_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 171)) % 3)::VARCHAR AS supplier_country_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 172)) % 3)::VARCHAR AS supplier_segment_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 173)) % 3)::VARCHAR AS supplier_certification_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 174)) % 3)::VARCHAR AS incoterm_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 175)) % 3)::VARCHAR AS payment_terms_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 176)) % 3)::VARCHAR AS currency_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 177)) % 3)::VARCHAR AS buyer_team_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 178)) % 3)::VARCHAR AS planner_group_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 179)) % 3)::VARCHAR AS fiscal_quarter_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 180)) % 3)::VARCHAR AS channel_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 181)) % 3)::VARCHAR AS customer_segment_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 182)) % 3)::VARCHAR AS program_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 183)) % 3)::VARCHAR AS ship_mode_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 184)) % 3)::VARCHAR AS hazmat_class_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 185)) % 3)::VARCHAR AS rohs_status_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 186)) % 3)::VARCHAR AS reach_status_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 187)) % 3)::VARCHAR AS country_of_origin_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 188)) % 3)::VARCHAR AS tariff_group_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 189)) % 3)::VARCHAR AS cost_center_rollup,
  GET(ARRAY_CONSTRUCT('Group A','Group B','Other'), ABS(HASH(p.part_id, l.plant, 190)) % 3)::VARCHAR AS profit_center_rollup
FROM (SELECT 'PN-' || LPAD(SEQ4() + 1, 4, '0') AS part_id FROM TABLE(GENERATOR(ROWCOUNT => 300))) p
CROSS JOIN (SELECT column1 AS plant FROM VALUES ('Lisle'),('Guadalajara'),('Penang'),('Shannon'),('Chengdu')) l;

CREATE OR REPLACE SEMANTIC VIEW MULTIAGENT_DEMO.DEMO.INVENTORY_SV
  TABLES (inv AS MULTIAGENT_DEMO.DEMO.INVENTORY_POSITIONS PRIMARY KEY (position_id) COMMENT = 'Current inventory positions by part and plant: on hand, safety stock, days of supply')
  FACTS (
    inv.on_hand_qty AS on_hand_qty,
    inv.safety_stock_qty AS safety_stock_qty,
    inv.avg_daily_usage AS avg_daily_usage,
    inv.standard_cost_usd AS standard_cost_usd,
    inv.below_safety_stock_flag AS IFF(on_hand_qty < safety_stock_qty, 1, 0),
    inv.inventory_value_usd AS on_hand_qty * standard_cost_usd
  )
  DIMENSIONS (
    inv.part_id AS part_id WITH SYNONYMS = ('part', 'part number', 'PN') COMMENT = 'Part number, format PN-####',
    inv.plant AS plant WITH SYNONYMS = ('site', 'factory') COMMENT = 'Plant holding the stock',
    inv.plant_region AS plant_region WITH SYNONYMS = ('plant region') COMMENT = 'Geographic region of the manufacturing plant. Used by the Inventory team to slice and filter KPIs. Allowed values: AMERICAS, EMEA, APAC. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.plant_country AS plant_country WITH SYNONYMS = ('plant country') COMMENT = 'Country where the plant operates. Used by the Inventory team to slice and filter KPIs. Allowed values: US, MX, DE, IE, CN, MY. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.business_unit AS business_unit WITH SYNONYMS = ('business unit') COMMENT = 'Business unit that owns the product line. Used by the Inventory team to slice and filter KPIs. Allowed values: Automotive, Industrial, Datacom, Medical, Consumer. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.product_line AS product_line WITH SYNONYMS = ('product line') COMMENT = 'Product line of the part. Used by the Inventory team to slice and filter KPIs. Allowed values: Connectors, Cable Assemblies, Sensors, Antennas, Switches. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.commodity_l1 AS commodity_l1 WITH SYNONYMS = ('commodity l1') COMMENT = 'Level-1 commodity classification. Used by the Inventory team to slice and filter KPIs. Allowed values: Metals, Plastics, Electronics, Packaging, Chemicals. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.commodity_l2 AS commodity_l2 WITH SYNONYMS = ('commodity l2') COMMENT = 'Level-2 commodity classification. Used by the Inventory team to slice and filter KPIs. Allowed values: Copper Alloy, Resin, PCB, Terminals, Corrugate, Plating. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.part_lifecycle AS part_lifecycle WITH SYNONYMS = ('part lifecycle') COMMENT = 'Engineering lifecycle state of the part. Used by the Inventory team to slice and filter KPIs. Allowed values: Prototype, Active, Mature, End of Life. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.part_criticality AS part_criticality WITH SYNONYMS = ('part criticality') COMMENT = 'Supply criticality rating from the risk team. Used by the Inventory team to slice and filter KPIs. Allowed values: A, B, C. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.make_or_buy AS make_or_buy WITH SYNONYMS = ('make or buy') COMMENT = 'Whether the part is manufactured or purchased. Used by the Inventory team to slice and filter KPIs. Allowed values: Make, Buy. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
