    inv.currency_rollup AS currency_rollup WITH SYNONYMS = ('currency rollup') COMMENT = 'Transaction currency before conversion to USD, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.buyer_team_rollup AS buyer_team_rollup WITH SYNONYMS = ('buyer team rollup') COMMENT = 'Procurement team responsible, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.planner_group_rollup AS planner_group_rollup WITH SYNONYMS = ('planner group rollup') COMMENT = 'Materials planning group, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.fiscal_quarter_rollup AS fiscal_quarter_rollup WITH SYNONYMS = ('fiscal quarter rollup') COMMENT = 'Fiscal quarter of the transaction, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.channel_rollup AS channel_rollup WITH SYNONYMS = ('channel rollup') COMMENT = 'Sales channel, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.customer_segment_rollup AS customer_segment_rollup WITH SYNONYMS = ('customer segment rollup') COMMENT = 'Customer industry segment, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
