    inv.ship_mode_rollup AS ship_mode_rollup WITH SYNONYMS = ('ship mode rollup') COMMENT = 'Primary shipment mode, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.hazmat_class_rollup AS hazmat_class_rollup WITH SYNONYMS = ('hazmat class rollup') COMMENT = 'Hazardous material classification, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    inv.rohs_status_rollup AS rohs_status_rollup WITH SYNONYMS = ('rohs status rollup') COMMENT = 'RoHS compliance status, rolled up for executive reporting. Used by the Inventory team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
