    co.cost_center_rollup AS cost_center_rollup WITH SYNONYMS = ('cost center rollup') COMMENT = 'Cost center charged, rolled up for executive reporting. Used by the Customer Orders team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.',
    co.profit_center_rollup AS profit_center_rollup WITH SYNONYMS = ('profit center rollup') COMMENT = 'Profit center for reporting, rolled up for executive reporting. Used by the Customer Orders team to slice and filter KPIs. Allowed values: Group A, Group B, Other. Conformed to the enterprise master data hub and refreshed nightly; records created before the 2019 ERP migration may be blank. Use for grouping and filtering only, never aggregate. When a user names one of the allowed values, filter on this column rather than searching free text.'
  )
  METRICS (
    co.total_order_value_usd AS SUM(co.line_value_usd) COMMENT = 'Total booked order value, USD',
    co.open_backlog_value_usd AS SUM(co.backlog_value_usd) COMMENT = 'Open backlog value (unshipped orders), USD',
    co.on_time_delivery_pct AS AVG(IFF(co.line_status = 'Shipped', co.shipped_on_time, NULL)) * 100 COMMENT = 'On-time delivery percentage for shipped lines',
    co.order_line_count AS COUNT(co.order_line_id) COMMENT = 'Number of order lines'
  )
  COMMENT = 'Customer order lines: bookings, open backlog and on-time delivery by customer, part and plant';

