-- BEFORE (1): each specialist wrapped in a stored procedure that calls DATA_AGENT_RUN and
-- returns only the text answer. Usage is logged so the specialists' tokens can be measured.
CREATE TABLE IF NOT EXISTS MULTIAGENT_DEMO.DEMO.SPECIALIST_USAGE_LOG (
  logged_at TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(), agent STRING, usage VARIANT);
CREATE OR REPLACE PROCEDURE MULTIAGENT_DEMO.DEMO.ASK_PROCUREMENT_AGENT(QUESTION STRING)
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS
$$
DECLARE
    full_result STRING;
    text_result STRING;
    request_json STRING;
BEGIN
    SELECT OBJECT_CONSTRUCT('messages', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT('role', 'user',
             'content', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT('type', 'text', 'text', :question)))))::STRING
      INTO :request_json;
    SELECT SNOWFLAKE.CORTEX.DATA_AGENT_RUN('MULTIAGENT_DEMO.DEMO.PROCUREMENT_AGENT', :request_json) INTO :full_result;
    INSERT INTO MULTIAGENT_DEMO.DEMO.SPECIALIST_USAGE_LOG (agent, usage)
      SELECT 'PROCUREMENT_AGENT', PARSE_JSON(:full_result):metadata:usage;
    SELECT LISTAGG(value:text::STRING, '') WITHIN GROUP (ORDER BY index) INTO :text_result
      FROM TABLE(FLATTEN(INPUT => PARSE_JSON(:full_result):content)) WHERE value:type = 'text';
    RETURN COALESCE(NULLIF(:text_result, ''), :full_result);
END;
$$;

